// A API já enfileirou uma mensagem por convite.
// Aqui fica o log agregado — útil para auditoria e para plugar
// integrações extras (CRM, e-mail, Slack) sem tocar no backend.
const body = $input.first().json.body ?? $input.first().json;
const invites = body.invites ?? [];
console.log(`[emptra] cotacao ${body.quotation?.code} disparada para ${invites.length} fornecedor(es)`);
return [{ json: { ok: true, code: body.quotation?.code ?? null, invites: invites.length } }];
